-- Sync elix_gifts with Bunny Storage /gifts/ inventory (48 video files, verified 2026-08-04).
-- App loads catalog from DB (GET /api/gifts/catalog). Idempotent upsert — safe to re-run.
BEGIN;

ON CONFLICT (gift_id) DO UPDATE SET
  name = EXCLUDED.name,
  gift_type = EXCLUDED.gift_type,
  coin_cost = EXCLUDED.coin_cost,
  animation_url = EXCLUDED.animation_url,
  is_active = EXCLUDED.is_active,
  battle_points = EXCLUDED.battle_points;

COMMIT;
